// Actions-only read-receipt API: authentication, finite metadata, no native IO.
#[tokio::test]
async fn im_receipt_routes_require_auth_no_store_strict_limits_and_expose_no_write_endpoint(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let path="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/im-receipts";
    let(status,_,body)=account_request(&served,reqwest::Method::GET,path,None,None).await;assert_eq!(status,StatusCode::UNAUTHORIZED);no_secrets(&body);
    let cookie=authenticate(&served).await;for suffix in ["?limit=0","?limit=129","?limit=1&token=fixture-must-not-echo"]{let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("{path}{suffix}"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}
    let(status,_,_)=account_request(&served,reqwest::Method::POST,path,Some(serde_json::json!({"accepted":true,"index":"7"})),Some(&cookie)).await;assert_eq!(status,StatusCode::METHOD_NOT_ALLOWED);assert!(state.app.app_accounts.list(100).await.unwrap().is_empty());
}
#[tokio::test]
async fn im_received_write_installation_requires_original_native_sync_and_stores_no_implicit_ready_or_start(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");
    let mut good=im_runtime_config_json(&cert.root);good["profile"]["im_sync"]=serde_json::json!({"receive":true});good["profile"]["im_receipts"]=serde_json::json!({"set_received":true});
    for change in [serde_json::json!({"set_received":false}),serde_json::json!({"set_received":true,"token":"fixture-must-not-echo"})]{let mut bad=good.clone();bad["profile"]["im_receipts"]=change;let(status,headers,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":bad})),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}
    let mut bad=good.clone();bad["profile"]["im_sync"]=serde_json::Value::Null;let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":bad})),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_secrets(&body);
    let(status,headers,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":good})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);no_store(&headers);no_secrets(&body);let line=created_line(&body);let view=state.app.app_accounts.get(&line,100).await.unwrap();assert_eq!(view.phase,"stopped");assert!(!view.incoming_message_ready&&!view.incoming_call_ready&&!view.outbound_authorized&&!view.io_cleanup_required);
    let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("/api/non-3gpp/accounts/{line}/im-receipts?limit=16"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::OK);no_store(&headers);assert_eq!(serde_json::from_str::<serde_json::Value>(&body).unwrap()["data"],serde_json::json!([]));
}
#[tokio::test]
async fn im_received_receipt_projection_keeps_full_index_uncertainty_and_never_reflects_private_context_or_ack_boolean(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":im_runtime_config_json(&cert.root)})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);
    state.app.database.with_conn(|c|c.execute("INSERT INTO app_voice_im_read_receipts(line_id,revision,identity_key,box_id,target_index,span_hash,attempt_nonce,run_nonce,scope_epoch,state,request_id,updated_at) VALUES(?1,1,?2,?3,?4,?5,?6,?7,?8,0,9,'2026-01-01T00:00:00Z')",rusqlite::params![line,vec![7u8;32],b"P2P/1_2".as_slice(),i64::MAX,vec![8u8;32],"a".repeat(32),"b".repeat(32),"private-scope"]).map_err(|_|"fixture")).unwrap();
    let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("/api/non-3gpp/accounts/{line}/im-receipts?limit=16"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::OK);no_store(&headers);let json:serde_json::Value=serde_json::from_str(&body).unwrap();assert_eq!(json["data"][0]["target_index"],"9223372036854775807");assert_eq!(json["data"][0]["state"],"uncertain");for hidden in ["P2P/1_2","private-scope","identity_key","span_hash","attempt_nonce","run_nonce","request_id"]{assert!(!body.contains(hidden));}assert!(state.app.app_accounts.im_messages(&line,16).unwrap().is_empty());assert!(state.app.app_accounts.messages(&line,16).unwrap().is_empty());
}
